def _target() -> dict | None:
    if os.environ.get("SCI_E2E_STATE"):
        return json.loads(Path(os.environ["SCI_E2E_STATE"]).read_text())
    if os.environ.get("SCI_E2E") == "1" and ENV.get("FLOWISE_SCI_API_KEY"):
